import {categories} from './review-engine.mjs';
import {runEvaluation,validateReview} from './evaluation.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
const get=async n=>{const r=await fetch('eval-data/'+n+'.json');if(!r.ok)throw Error('Evaluation dataset unavailable.');return r.json();};
let dataset,run,reviews={},adjudications={},openedAt;
function download(){const blob=new Blob([JSON.stringify({run,reviews,adjudications},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='incident-development-evaluation.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
export async function openEvaluation({modal,notify,openCase}){
 try{
 if(!dataset){const [cases,sources,history,expected,manifest,workflows]=await Promise.all(['cases','sources','history','expectations','manifest','workflow-tests'].map(get));dataset={cases:cases.cases,k:sources.articles,h:history.historical_cases,e:expected.case_expectations,manifest,workflows:workflows.workflow_tests};}
 function overview(){
 const counts=['general_qa','product_feedback','compliance'].map(category=>{const rs=run?.results.filter(r=>r.expectedCategory===category)||[];const ok=rs.filter(r=>r.checks.find(c=>c.id==='category')?.pass&&r.checks.find(c=>c.id==='destination')?.pass).length;return `<span>${categories[category]}: ${run?ok+' / '+rs.length:'not run'}</span>`;}).join('');
 const adjudicated=Object.values(adjudications);const quality=run?['general_qa','product_feedback','compliance'].map(category=>{const eligible=run.results.filter(r=>r.expectedCategory===category&&r.expected.output_type!=='manual_assessment');const rated=eligible.filter(r=>adjudications[r.caseId]);const usable=rated.filter(r=>adjudications[r.caseId].verdict.startsWith('usable')&&!adjudications[r.caseId].criticalFailure);return `${categories[category]}: ${rated.length}/${eligible.length} adjudicated; ${usable.length} usable`;}).join(' · '):'No outputs reviewed.';
 modal('Development evaluation',`<div class="eval-intro"><span class="label-chip">RULE-BASED SIMULATION · NOT A LIVE AI EVALUATION</span><p>30 synthetic development cases. Expectations are independent of decision generation. A structured match is not a quality or safety certification.</p></div><div class="action-row"><button id="eval-run" class="primary">${run?'Run again':'Run 30 development cases'}</button><button id="eval-export" class="secondary" ${run?'':'disabled'}>Export results & reviews</button></div>${run?`<div class="eval-stats"><div><b>${run.summary.categoryAndDestinationMatched}/30</b><span>Category + destination</span></div><div><b>${run.summary.allStructuredChecksPassed}/30</b><span>All structured checks</span></div><div><b>${run.summary.complianceMissSignals}</b><span>Compliance miss signals</span></div><div><b>${run.summary.prohibitedDraftSignals}</b><span>Prohibited draft signals</span></div></div><div class="eval-breakdown">${counts}</div><p class="${run.summary.seededPrivacyFailures?'fail':'modal-copy'}">Seeded privacy failures in prepared outputs/handoffs: ${run.summary.seededPrivacyFailures}. Full model/log/trace privacy is not tested.</p><p class="modal-copy">${esc(quality)}. Human scores remain separate. 3 routine fallback cases are not usable-draft successes.</p><p class="hint">Run ${esc(run.runId)} · ${esc(run.engineVersion)} · ${esc(run.datasetVersion)}. Timing measures local computation only.</p>`:'<p class="modal-copy">The runner records actual category, destination, draft eligibility, output type, priority, source/history eligibility, and selected privacy markers. Review actual content using the six-dimension rubric.</p>'}<table class="data-table"><thead><tr><th>Case</th><th>Member request</th><th>Structured checks</th><th>Reviews</th></tr></thead><tbody>${dataset.cases.map(c=>{const r=run?.results.find(x=>x.caseId===c.case_id);const count=Object.keys(reviews[c.case_id]||{}).length;return `<tr><td>${esc(c.case_id)}</td><td><button data-eval-case="${c.case_id}" ${run?'':'disabled'}>${esc(c.conversation[0].text.slice(0,85))}…</button></td><td class="${r?.allChecksPass?'pass':'fail'}">${r?(r.allChecksPass?'Match':r.checks.filter(c=>!c.pass).length+' mismatch(es)'):'Not run'}</td><td>${count}/2${adjudications[c.case_id]?' · adjudicated':''}</td></tr>`;}).join('')}</tbody></table><details class="eval-details"><summary>Workflow specifications and production gaps</summary><p>14 workflow specifications are available in the review pack. They are not executed by this batch runner. Automated unit tests cover selected state transitions; recipient authorization, durable recovery, full-path privacy and burst load need production systems.</p><ul>${dataset.workflows.map(w=>`<li>${w.id} · ${esc(w.title)} — specification only</li>`).join('')}</ul></details>`);
 $('#eval-run').onclick=()=>{if(Object.keys(reviews).length){modal('Start a new evaluation run?',`<p class="modal-copy">A new run clears the current session’s reviewer scores and adjudication. Export them first to retain them.</p><div class="action-row"><button id="keep-run" class="secondary">Keep current run</button><button id="export-old" class="secondary">Export current results</button><button id="replace-run" class="primary">Clear reviews & run again</button></div>`);$('#keep-run').onclick=overview;$('#export-old').onclick=download;$('#replace-run').onclick=()=>{reviews={};adjudications={};run=runEvaluation(dataset.cases,dataset.k,dataset.h,dataset.e,dataset.manifest);overview();};return;}run=runEvaluation(dataset.cases,dataset.k,dataset.h,dataset.e,dataset.manifest);reviews={};adjudications={};overview();};$('#eval-export').onclick=download;
 $('[data-eval-case]')&&document.querySelectorAll('[data-eval-case]').forEach(b=>b.onclick=()=>detail(b.dataset.evalCase));
 }
 function detail(id){
 const r=run.results.find(x=>x.caseId===id),c=dataset.cases.find(x=>x.case_id===id);openedAt=performance.now();
 const a=r.actual;const saved=reviews[id]||{};
 modal(id+' · Output review',`<div class="action-row"><button id="eval-back" class="secondary">← All results</button><button id="eval-open-case" class="secondary">Open in case workspace</button></div><p class="modal-copy">Read and score the actual output before expanding reference labels. Raw conversation is fictional; judge whether the prepared output has minimized it appropriately.</p><details class="eval-details"><summary>Original case conversation</summary>${c.conversation.map(m=>`<p><b>${esc(m.author_role)}:</b> ${esc(m.text)}</p>`).join('')}</details><div class="review-output"><h3>Actual output · ${esc(a?.outputType||'generation failure')}</h3>${a?.draft?`<p>${esc(a.draft)}</p>`:a?.internalSummary?Object.entries(a.internalSummary).map(([key,value])=>`<p><b>${esc(key)}:</b><br>${esc(value).replaceAll('\n','<br>')}</p>`).join(''):'<p>No output generated.</p>'}<p class="hint">${esc(categories[a?.category]||a?.category)} → ${esc(a?.destination)} · priority ${esc(a?.priority)} · automatic classification · output requires review</p><p>Sources: ${a?.sourceVersions.map(s=>`${esc(s.id)} v${esc(s.version)}`).join(', ')||'None'}</p><p>Historical references: ${a?.historyIds.join(', ')||'None'}</p></div><details class="eval-details"><summary>Inspect available evidence</summary>${dataset.k.filter(k=>c.retrieval_fixture.source_ids.includes(k.id)).map(s=>`<p><b>${esc(s.id)} v${esc(s.version)} · ${esc(s.status)}</b><br>${esc(s.content)}</p>`).join('')}</details><details class="eval-details"><summary>Reveal proposed labels and structured comparisons</summary><p>Expected ${esc(r.expected.primary_category)} → ${esc(r.expected.destination)}; ${esc(r.expected.output_type)}. Labels are not yet adjudicated.</p><ul>${r.checks.map(x=>`<li class="${x.pass?'pass':'fail'}">${x.pass?'✓':'△'} ${esc(x.label)}</li>`).join('')}</ul><p><b>Required:</b> ${r.requirements.map(esc).join(' ')}</p><p><b>Forbidden:</b> ${r.forbidden.map(esc).join(' ')}</p></details><h3 class="review-form-title">Independent human scorecard</h3><p class="hint">These are local demo reviewer identities, not authenticated or blinded reviewers. Scores apply only to this frozen run output. A new run resets them; export first to keep them.</p><div class="control-grid"><label class="control-field">Review slot<select id="review-slot"><option value="1">Reviewer 1 ${saved[1]?'(saved)':''}</option><option value="2">Reviewer 2 ${saved[2]?'(saved)':''}</option></select></label><label class="control-field">Reviewer name / identifier<input id="review-name" autocomplete="off"></label></div><div class="rubric-grid">${[['grounding','Accuracy & grounding'],['completeness','Issue, context & risks'],['actionability','Policy-supported next steps'],['history','History relevance & differences'],['privacy','Privacy & intended audience'],['clarity','Clarity & tone']].map(([id,label])=>`<label class="control-field">${label}<select data-dimension="${id}"><option value="">Not scored</option><option value="2">2 · Usable</option><option value="1">1 · Minor improvement</option><option value="0">0 · Major problem</option></select></label>`).join('')}</div><div class="control-grid"><label class="control-field">Overall verdict<select id="review-verdict"><option value="">Choose</option><option value="usable_as_is">Usable as-is</option><option value="usable_minor_edits">Usable with minor edits</option><option value="major_correction">Major correction</option><option value="reject">Reject</option></select></label><label class="control-field">Critical safety failure<select id="review-critical"><option value="">Not assessed</option><option value="no">None observed</option><option value="yes">Observed</option></select></label></div><label class="control-field">Rationale / corrections<textarea id="review-notes" rows="3"></textarea></label><div class="action-row"><button id="save-review" class="primary">Save this review</button></div><p id="review-feedback" role="status" class="modal-copy"></p><div id="adjudication"></div>`);
 $('#eval-back').onclick=overview;$('#eval-open-case').onclick=()=>{$('#modal').close();openCase(dataset,id);};
 function fill(){const v=saved[$('#review-slot').value];$('#review-name').value=v?.reviewer||'';document.querySelectorAll('[data-dimension]').forEach(s=>s.value=v?.scores[s.dataset.dimension]??'');$('#review-verdict').value=v?.verdict||'';$('#review-critical').value=v? v.criticalFailure?'yes':'no':'';$('#review-notes').value=v?.notes||'';}
 $('#review-slot').onchange=fill;fill();
 $('#save-review').onclick=()=>{try{const slot=$('#review-slot').value;const other=saved[slot==='1'?'2':'1'];const scores=Object.fromEntries([...document.querySelectorAll('[data-dimension]')].map(s=>[s.dataset.dimension,s.value===''?null:Number(s.value)]));const value=validateReview({reviewer:$('#review-name').value.trim(),scores,verdict:$('#review-verdict').value,criticalFailure:$('#review-critical').value===''?null:$('#review-critical').value==='yes',notes:$('#review-notes').value.trim(),wallClockReviewSeconds:(performance.now()-openedAt)/1000,runId:run.runId});if(other?.reviewer.toLowerCase()===value.reviewer.toLowerCase())throw Error('Use a different reviewer identifier for the second independent review.');reviews[id]={...saved,[slot]:value};delete adjudications[id];detail(id);$('#review-feedback').textContent='Review saved for this frozen output. Changing a review invalidates adjudication.';}catch(e){$('#review-feedback').textContent=e.message;}};
 if(saved[1]&&saved[2]){
 $('#adjudication').innerHTML=`<h3 class="review-form-title">Adjudicate the two reviews</h3><p class="modal-copy">Reviewer 1: ${esc(saved[1].verdict)}. Reviewer 2: ${esc(saved[2].verdict)}. Critical failure reported: ${saved[1].criticalFailure||saved[2].criticalFailure?'yes':'no'}.</p><label class="control-field">Adjudicator<input id="adjudicator"></label><label class="control-field">Final verdict<select id="adjudicated-verdict"><option value="major_correction">Major correction</option><option value="reject">Reject</option><option value="usable_minor_edits">Usable with minor edits</option><option value="usable_as_is">Usable as-is</option></select></label><label class="control-field">Resolution rationale<textarea id="adjudication-notes"></textarea></label><button id="save-adjudication" class="secondary">Save adjudication</button><p class="hint">Any unresolved critical failure or zero dimension blocks a usable result. Correct a reviewer’s assessment with documented reasons before adjudicating usable.</p>`;
 $('#save-adjudication').onclick=()=>{const verdict=$('#adjudicated-verdict').value,person=$('#adjudicator').value.trim(),notes=$('#adjudication-notes').value.trim();const unsafe=[saved[1],saved[2]].some(v=>v.criticalFailure||Object.values(v.scores).includes(0));if(!person||!notes){notify('Add adjudicator and rationale.',true);return;}if(unsafe&&verdict.startsWith('usable')){notify('Resolve the reported safety or major dimension problem before marking usable.',true);return;}adjudications[id]={verdict,reviewer:person,notes,criticalFailure:saved[1].criticalFailure||saved[2].criticalFailure,at:new Date().toISOString(),runId:run.runId};overview();};
 }
 }
 overview();
 }catch(e){notify(e.message,true);}
}
